import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import { normalizeErrorStackOptions } from './dist/error-options.js';
import { processStackString, processStackFrames } from './dist/error-stack.js';
assert.equal(normalizeErrorStackOptions(null), undefined);
const opts = normalizeErrorStackOptions({mode:'string', maxStackLines:2, stripInternalFrames:'node'});
const stack = 'Error: x\n    at node:internal/x\n    at /app/a.js:1:2';
assert.equal(processStackString(stack, opts), 'Error: x');
assert.equal(processStackFrames(stack, opts).length, 2);
for (const container of [e=>e, e=>[e], e=>({e}), e=>new Map([['e',e]]), e=>new Set([e])]) {
 const s=new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',sanitizeMessage:true}}); s.allowErrorProps('stackFrames');
 const e=new Error('x',{cause:new Error('a@b.com')}); e.stack='Error: x\n    at /tmp/a.js:1:2';
 const x=s.parse(s.stringify(container(e))); const out=x instanceof Map?x.get('e'):x instanceof Set?[...x][0]:Array.isArray(x)?x[0]:x.e??x;
 assert.equal(out.stack, 'Error: x\nat /tmp/a.js:1:2'); assert.equal(out.cause.message,'[redacted]');
}
const s=new SuperJSON({errorStack:{mode:'string',includeCauses:'deep'}}); s.allowErrorProps('stack'); const e=new Error('x',{cause:new Error('y')}); const other=new SuperJSON(); assert(other.deserialize(s.serialize(e)).cause instanceof Error);
console.log('Focused checks passed');
